'use client'

import Link from 'next/link'
import { useEffect, useState, type ChangeEvent } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import { downloadProductTemplate, type ImportPreview, type ImportRecord, vendorImportService } from '@/lib/vendor/imports'
import { CatalogFeedback } from '../components/CatalogFeedback'
import { ImportErrorTable } from '../components/ImportErrorTable'
import { ImportPreviewTable } from '../components/ImportPreviewTable'
import { ImportStatusBadge } from '../components/ImportStatusBadge'

export default function VendorImportsPage() {
  const [vendorId, setVendorId] = useState<string | null>(null); const [uploadedBy, setUploadedBy] = useState('Vendor user'); const [history, setHistory] = useState<ImportRecord[]>([]); const [preview, setPreview] = useState<ImportPreview | null>(null); const [loading, setLoading] = useState(true); const [isValidating, setIsValidating] = useState(false); const [isImporting, setIsImporting] = useState(false); const [error, setError] = useState('')
  useEffect(() => { void createClient().auth.getUser().then(async ({ data: { user } }) => { if (user && (getUserRole(user) === 'vendor' || getUserRole(user) === 'admin')) { setVendorId(user.id); setUploadedBy(user.email ?? 'Vendor user'); setHistory(await vendorImportService.listHistory(user.id)) } setLoading(false) }) }, [])
  async function handleUpload(event: ChangeEvent<HTMLInputElement>) { const file = event.target.files?.[0]; if (!file || !vendorId) return; const extension = file.name.toLowerCase(); if (!extension.endsWith('.csv') && !extension.endsWith('.xlsx')) { setError('Upload a CSV or XLSX file.'); return } setError(''); setPreview(null); setIsValidating(true); try { setPreview(await vendorImportService.createPreview(vendorId, uploadedBy, file.name, file)); setHistory(await vendorImportService.listHistory(vendorId)) } catch { setError('We could not read this file. Confirm it is a valid CSV or XLSX workbook.') } finally { setIsValidating(false); event.target.value = '' } }
  async function submitImport() { if (!vendorId || !preview || preview.status !== 'ready_for_import') return; setIsImporting(true); setError(''); try { await vendorImportService.submit(vendorId, preview.importId); setHistory(await vendorImportService.listHistory(vendorId)); setPreview(null) } catch { setError('The import could not be completed. Your valid records remain available to retry.') } finally { setIsImporting(false) } }
  if (loading) return <main className="vendor-page"><div className="catalog-page-shell"><CatalogFeedback type="loading">Loading import workspace...</CatalogFeedback></div></main>
  return <main className="vendor-page"><header className="vendor-header"><Link href="/vendor" className="logo logo-active">Furnish<span>AI</span></Link><nav><Link href="/vendor/products" className="btn-skip">Catalog</Link><span className="vendor-header-label">Bulk import</span></nav></header><div className="import-page-shell"><div className="catalog-page-heading"><div><p className="vendor-eyebrow">Vendor portal / Phase 03</p><h1>Bulk catalog upload</h1><p>Prepare many listings at once, validate them before import, and fix only the rows that need attention.</p></div><button type="button" className="btn-skip" onClick={downloadProductTemplate}>Download template</button></div><section className="import-upload-layout"><div className="import-upload-card"><p className="vendor-eyebrow">1 / Upload</p><h2>Start with the official template</h2><p>Use CSV or XLSX with one product per row. Required columns are name, sku, category, description, price, stock, imageUrl, and variants.</p><label className="import-dropzone"><input type="file" accept=".csv,.xlsx" onChange={(event) => void handleUpload(event)} /><strong>{isValidating ? 'Validating file...' : 'Choose CSV or XLSX file'}</strong><span>Files are checked before any product records are created.</span></label><button type="button" className="import-template-link" onClick={downloadProductTemplate}>Download a blank template</button></div><div className="import-rules-card"><p className="vendor-eyebrow">Before you upload</p><h2>Keep the file clean</h2><ul><li>Use a unique SKU for every row.</li><li>Categories must match the approved catalog list.</li><li>Prices must be positive and stock must be a whole number.</li><li>Image URLs must use HTTP or HTTPS.</li><li>Variants use <code>Name=...|SKU=...|Price=...|Stock=...</code>.</li></ul></div></section>{error ? <CatalogFeedback type="error">{error}</CatalogFeedback> : null}{isValidating ? <CatalogFeedback type="loading">Reading rows and checking each column...</CatalogFeedback> : null}{preview ? <section className="import-preview-section"><div className="import-preview-heading"><div><p className="vendor-eyebrow">2 / Review</p><h2>{preview.fileName}</h2></div><ImportStatusBadge status={preview.status} /></div><div className="import-count-grid"><div><strong>{preview.totalRecords}</strong><span>Total records</span></div><div className="import-count-valid"><strong>{preview.validRecords}</strong><span>Valid records</span></div><div className="import-count-invalid"><strong>{preview.invalidRecords}</strong><span>Invalid records</span></div></div>{preview.validRows.length ? <ImportPreviewTable rows={preview.validRows} /> : null}<ImportErrorTable errors={preview.errors} /><div className="import-preview-actions">{preview.errors.length ? <p>Correct the source file and upload it again to retry validation.</p> : <p>Valid records will be created as draft products and remain subject to the existing approval workflow.</p>}{preview.errors.length ? null : <button type="button" className="btn-next" disabled={isImporting} onClick={() => void submitImport()}>{isImporting ? 'Importing...' : 'Submit valid records'}</button>}</div></section> : null}<section className="import-history-section"><div className="import-history-heading"><div><p className="vendor-eyebrow">3 / History</p><h2>Previous imports</h2></div><span>{history.length} imports</span></div>{history.length ? <div className="import-history-wrap"><table className="import-history-table"><caption>Bulk catalog import history</caption><thead><tr><th>File name</th><th>Uploaded</th><th>Records</th><th>Successful</th><th>Failed</th><th>Status</th><th>Uploaded by</th><th>Actions</th></tr></thead><tbody>{history.map((record) => <tr key={record.id}><td><strong>{record.fileName}</strong></td><td>{new Date(record.uploadedAt).toLocaleDateString('en-IN')}</td><td>{record.totalRecords}</td><td>{record.successfulRecords}</td><td>{record.failedRecords}</td><td><ImportStatusBadge status={record.status} /></td><td>{record.uploadedBy}</td><td>{record.errors.length ? <button type="button" className="import-action" onClick={() => vendorImportService.downloadErrorReport(record)}>Download errors</button> : <span className="import-no-action">No errors</span>}</td></tr>)}</tbody></table></div> : <div className="catalog-empty import-empty"><span className="catalog-empty-mark">↥</span><h2>No imports yet</h2><p>Your completed upload history will appear here.</p></div>}</section></div></main>
}